<template><SilkRoadWorkspace title="项目生成任务"><ProjectStageNav :project-id="projectId" /><section class="page-head"><div><h1>任务与分发进度</h1><p>跟踪图片、视频、数字人、导出和渠道分发任务。</p></div><el-button :loading="loading" @click="load">刷新状态</el-button></section><div class="stats"><article><strong>{{ allTasks.length }}</strong><span>全部任务</span></article><article><strong>{{ processing }}</strong><span>处理中</span></article><article><strong>{{ completed }}</strong><span>已完成</span></article><article><strong>{{ failed }}</strong><span>需处理</span></article></div><el-table v-loading="loading" :data="allTasks" empty-text="当前项目暂无生成任务"><el-table-column label="任务类型" prop="displayType" min-width="150"/><el-table-column label="状态" min-width="120"><template #default="scope"><el-tag :type="tone(scope.row.status)">{{ statusText(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="进度" min-width="220"><template #default="scope"><el-progress :percentage="Number(scope.row.progress??(scope.row.status==='completed'?100:0))" /></template></el-table-column><el-table-column label="状态说明" prop="message" min-width="260"/><el-table-column label="更新时间" prop="updated_at" min-width="180"/></el-table></SilkRoadWorkspace></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import ProjectStageNav from '@/components/projects/ProjectStageNav.vue';import{projectAPI}from'@/api/project';const route=useRoute(),projectId=String(route.params.id),loading=ref(false),data=ref<any>({images:[],videos:[],tasks:[]});const normalize=(items:any[],type:string)=>items.map(x=>({...x,displayType:type,message:x.message||x.prompt||'等待状态更新'}));const allTasks=computed(()=>[...normalize(data.value.images||[],'营销图片生成'),...normalize(data.value.videos||[],'营销视频生成'),...normalize(data.value.tasks||[],'内容处理任务')]);const processing=computed(()=>allTasks.value.filter(x=>['pending','processing','running'].includes(x.status)).length),completed=computed(()=>allTasks.value.filter(x=>['completed','success'].includes(x.status)).length),failed=computed(()=>allTasks.value.filter(x=>['failed','error'].includes(x.status)).length);const statusText=(s:string)=>({pending:'等待中',processing:'处理中',running:'处理中',completed:'已完成',success:'已完成',failed:'失败',error:'失败'}[s]||s||'等待中');const tone=(s:string)=>(['completed','success'].includes(s)?'success':['failed','error'].includes(s)?'danger':['processing','running'].includes(s)?'warning':'info');const load=async()=>{loading.value=true;try{data.value=await projectAPI.getTasks(projectId)}finally{loading.value=false}};onMounted(load)</script>
<style scoped>.page-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}.page-head h1{font-size:29px;margin-bottom:7px}.page-head p{color:var(--text-secondary)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.stats article{padding:18px;border:1px solid var(--border-primary);border-radius:16px;background:var(--bg-card)}.stats strong{display:block;font-size:28px}.stats span{color:var(--text-muted);font-size:13px}@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}}</style>
